function readCart(){try{const v=JSON.parse(localStorage.getItem('asik-cart')||'{}');return v&&typeof v==='object'?v:{}}catch{return {}}}
function readCartProducts(){try{const v=JSON.parse(localStorage.getItem('asik-cart-products')||'{}');return v&&typeof v==='object'?v:{}}catch{return {}}}
function saveCart(){try{localStorage.setItem('asik-cart',JSON.stringify(cart));localStorage.setItem('asik-cart-products',JSON.stringify(cartProductCache))}catch(e){console.warn('Cart could not be persisted',e)}renderCartCount();renderCart()}
// Keep a product snapshot alongside quantities so cart remains visible while Firebase is loading/offline.
window.addEventListener('pageshow',()=>{cart=readCart();cartProductCache=readCartProducts();renderCartCount();renderCart()});
window.addEventListener('storage',e=>{if(e.key==='asik-cart'||e.key==='asik-cart-products'){cart=readCart();cartProductCache=readCartProducts();renderCartCount();renderCart()}});
function makeBengaliBill(orderId, order){const rows=(order.items||[]).map(i=>`<tr><td>${escapeHtml(i.name||'পণ্য')}<small>${escapeHtml(i.unit||'')}</small></td><td>${Number(i.quantity)||1}</td><td>${money(i.price)}</td><td>${money((Number(i.price)||0)*(Number(i.quantity)||1))}</td></tr>`).join('');return `<section class="handbill" id="orderBill"><div class="bill-top"><div class="bill-stamp">ASIK<br>STORE</div><div><div class="bill-shopname">আসিক স্টোর</div><div class="bill-subtitle">আপনার এলাকার বিশ্বস্ত বাজার</div><div class="bill-subtitle">অর্ডার বিল / Order Bill · হাতে-লেখা স্টাইল</div></div></div><div class="bill-meta"><span>বিল নং: ${escapeHtml(orderId)}</span><span>তারিখ: ${new Date().toLocaleDateString('bn-IN')}</span></div><div class="bill-customer">ক্রেতার নাম: ${escapeHtml(order.customerName||'—')}<br>মোবাইল: ${escapeHtml(order.phone||'—')}<br>ঠিকানা: ${escapeHtml(order.address||'—')}</div><table class="bill-table"><thead><tr><th>পণ্যের নাম</th><th>সংখ্যা</th><th>দর</th><th>মোট</th></tr></thead><tbody>${rows}</tbody></table><div class="bill-totals"><div><span>পণ্যের মোট</span><b>${money(order.subtotal)}</b></div>${storeSettings.hideDeliveryFee?'':`<div><span>ডেলিভারি চার্জ</span><b>${order.deliveryFee==null?'পরে জানানো হবে':money(order.deliveryFee)}</b></div>`}<div class="bill-grand"><span>সর্বমোট</span><b>${money(order.total??order.subtotal)}</b></div></div><div class="bill-payment">পেমেন্ট: ${escapeHtml(order.paymentMethod==='cod'?'ক্যাশ অন ডেলিভারি':'UPI')} · স্ট্যাটাস: ${escapeHtml(order.status||'pending')}</div>${order.customerConfirmed?'<div class="bill-payment">ক্রেতার কনফার্মেশন: নিশ্চিত ✓</div>':''}<div class="bill-thanks">ধন্যবাদ, আবার আসবেন!<br><span>এই বিলটি ASIK STORE থেকে স্বয়ংক্রিয়ভাবে তৈরি।</span></div></section>`}
async function confirmCustomerOrder(orderId, button){
 if(!currentUser||!configReady){showNotice('অর্ডার কনফার্ম করতে লগইন করুন।',true);return}
 if(button){button.disabled=true;button.textContent='কনফার্ম হচ্ছে…'}
 try{await updateDoc(doc(db,'orders',orderId),{customerConfirmed:true,customerConfirmedAt:serverTimestamp()});if(button){button.textContent='✓ অর্ডার কনফার্ম হয়েছে';button.classList.add('confirmed-order-btn')}showNotice('আপনার অর্ডার কনফার্ম হয়েছে।');}
 catch(e){if(button){button.disabled=false;button.textContent='✓ অর্ডার কনফার্ম করুন'}showNotice('কনফার্ম করতে পারেনি। Firestore Rules আপডেট করতে হবে: '+friendlyError(e),true)}
}
